export const fontFoundations = {
  body: {
    medium: "normal normal 400 14px 'Work Sans'",
    small: "normal normal 400 14px 'Work Sans'",
    large: "normal normal 400 16px 'Work Sans'",
    xsmall: "normal normal 400 12px 'Work Sans'",
  },
  subheader: {
    large: ' normal 600  16px Work Sans ',
    small: ' normal 600  12px Work Sans ',
  },
};

// Tokens from the former Hexa theme.
export const fontFamilies = {
  heading: 'Barlow, San Francisco, Roboto, Segoe UI, Helvetica, sans-serif',
